        /**
         * @description One context's configured storage provider and the state of its most recent persistence attempt.
         *
         *     Reported from the repository's already-tracked sync status rather than by probing storage: the
         *     document is read once at startup and held in memory, so a fresh read would prove nothing about
         *     whether writes are landing, and a fresh Google Drive round-trip would put a network call on
         *     every probe.
         */
        HealthContextDTO: {
            /** @description Why the last persistence attempt failed, when it did. */
            lastError?: null | string;
            /**
             * Format: date-time
             * @description When a write last reached storage, or null if none has since startup.
             */
            lastSuccessfulSaveUtc?: null | string;
            /** @description The configured repository provider (e.g. "LocalJson", "GoogleDrive"). */
            provider?: null | string;
            /** @description Idle, Pending, Saving or Failed. */
            sync: string;
        };
        /** @description Both bounded contexts' storage health. */
        HealthContextsDTO: {
            cashFlow: components["schemas"]["HealthContextDTO"];
            investment: components["schemas"]["HealthContextDTO"];
        };
        /**
         * @description Result of the API health check.
         *
         *     The endpoint answers 200 whenever the process is serving, including when a context's storage is
         *     failing - the body says so instead. It is used as a readiness probe (CI's boot loop, and any
         *     container healthcheck), and failing it on a dependency would have an orchestrator restart the
         *     container over, say, a Google Drive outage it cannot fix. That restart would also be the worst
         *     available response: startup re-reads the document from the same failing storage.
         */
        HealthStatusDTO: {
            /** @description Per-bounded-context storage state, so one call answers "is anything wrong". */
            contexts: components["schemas"]["HealthContextsDTO"];
            /** @description Always "ok" when the API is reachable and responding. Read the contexts for storage. */
            status: string;
        };
